INSERT INTO public.user_roles (user_id, role) SELECT id, 'admin' FROM auth.users WHERE lower(email) = 'mayanktakpc@gmail.com' AND email_confirmed_at IS NOT NULL ON CONFLICT (user_id, role) DO NOTHING; CREATE OR REPLACE FUNCTION public.grant_admin_for_mayanktakpc() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF new.email_confirmed_at IS NOT NULL AND lower(new.email) = 'mayanktakpc@gmail.com' THEN INSERT INTO public.user_roles (user_id, role) VALUES (new.id, 'admin') ON CONFLICT (user_id, role) DO NOTHING; END IF; RETURN new; END; $$; DROP TRIGGER IF EXISTS on_auth_user_created_admin_email ON auth.users; CREATE TRIGGER on_auth_user_created_admin_email AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.grant_admin_for_mayanktakpc(); DROP TRIGGER IF EXISTS on_auth_user_confirmed_admin_email ON auth.users; CREATE TRIGGER on_auth_user_confirmed_admin_email AFTER UPDATE OF email_confirmed_at ON auth.users FOR EACH ROW WHEN (old.email_confirmed_at IS NULL AND new.email_confirmed_at IS NOT NULL) EXECUTE FUNCTION public.grant_admin_for_mayanktakpc();